test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const line1Vat = Math.round((9500 * 10 * 21) / 100);
  const line2Vat = Math.round((37 * 100 * 9) / 100);
  const line3Vat = 0;
  const expectedVat = line1Vat + line2Vat + line3Vat;

  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

test('invoiceTotals VAT with discount', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const lineTotal_ = 10 * 9500;
  const lineDiscount_ = Math.round((lineTotal_ * 10) / 100);
  const netAmount = lineTotal_ - lineDiscount_;
  const expectedVat = Math.round((netAmount * 21) / 100);

  assert.equal(totals.discount, lineDiscount_);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

